<script setup lang="ts">
import { Close } from '@element-plus/icons-vue'; import type { Track } from '../types'
const props=defineProps<{open:boolean;track:Track|null}>(); const emit=defineEmits<{close:[]}>(); const fmt=(v?:number)=>v==null?'—':`${Math.floor(v/60)}:${String(Math.floor(v%60)).padStart(2,'0')}`
</script>
<template><aside v-if="props.open" class="player-drawer info-panel" aria-label="作品信息"><header><div><span class="eyebrow">TRACK INFO</span><h3>作品信息</h3></div><button class="icon-button" aria-label="关闭作品信息" @click="emit('close')"><Close/></button></header><template v-if="props.track"><div class="info-cover"><img v-if="props.track.coverUrl" :src="props.track.coverUrl" alt=""/><span v-else>♪</span></div><h2>{{props.track.title}}</h2><p class="muted">{{props.track.styleTags||'暂无风格信息'}}</p><dl class="info-grid"><div><dt>模型</dt><dd>{{props.track.modelVersion||'—'}}</dd></div><div><dt>时长</dt><dd>{{fmt(props.track.duration)}}</dd></div><div><dt>来源</dt><dd>{{props.track.sourceType||'生成'}}</dd></div><div><dt>创建时间</dt><dd>{{new Date(props.track.createdAt).toLocaleString()}}</dd></div></dl><h4>歌词</h4><pre class="lyrics">{{props.track.lyrics||'这首作品没有歌词。'}}</pre></template></aside></template>
